// Normalizare si clasificare articole RSS
const categoryMap = {
  'rss-1': 'tech',
  'rss-2': 'economy',
  'rss-3': 'sport',
  'rss-4': 'science',
  'rss-5': 'health',
  'rss-6': 'world'
};

const techKeywords = ['tech', 'ai', 'software', 'hardware', 'cyber', 'digital', 'robot', 'code', 'app', 'computer', 'internet', 'data', 'cloud', 'hack'];
const econKeywords = ['economy', 'market', 'stock', 'trade', 'gdp', 'inflation', 'bank', 'finance', 'business', 'invest', 'money', 'price', 'cost', 'revenue'];
const sportKeywords = ['sport', 'football', 'soccer', 'basketball', 'tennis', 'cricket', 'rugby', 'olympics', 'champion', 'league', 'match', 'player', 'team', 'win'];
const sciKeywords = ['science', 'research', 'study', 'climate', 'environment', 'space', 'nasa', 'discovery', 'planet', 'genome', 'vaccine', 'physics', 'biology'];
const healthKeywords = ['health', 'medical', 'hospital', 'disease', 'virus', 'cancer', 'drug', 'treatment', 'doctor', 'patient', 'mental', 'diet', 'exercise'];

function guessCategory(title, description) {
  const text = ((title || '') + ' ' + (description || '')).toLowerCase();
  if (techKeywords.some(k => text.includes(k))) return 'tech';
  if (econKeywords.some(k => text.includes(k))) return 'economy';
  if (sportKeywords.some(k => text.includes(k))) return 'sport';
  if (sciKeywords.some(k => text.includes(k))) return 'science';
  if (healthKeywords.some(k => text.includes(k))) return 'health';
  return 'world';
}

function estimateReadTime(text) {
  if (!text) return 2;
  const wordCount = text.trim().split(/\s+/).length;
  return Math.max(1, Math.round(wordCount / 200));
}

const seen = new Set();
const results = [];

for (const item of $input.all()) {
  const data = item.json;
  const url = data.link || data.url || data.guid || '';
  if (!url || seen.has(url)) continue;
  seen.add(url);

  const title = (data.title || '').trim();
  const description = (data.contentSnippet || data.content || data.description || data.summary || '').replace(/<[^>]+>/g, '').trim();
  const pubDate = data.pubDate || data.isoDate || data.published || null;
  const category = guessCategory(title, description);
  const readTime = estimateReadTime(description);

  results.push({
    json: {
      title,
      source: 'BBC News',
      image_url: data.enclosure?.url || data['media:thumbnail']?.['$']?.url || null,
      summary: description.slice(0, 500),
      article_url: url,
      read_time_minutes: readTime,
      category,
      published_at: pubDate ? new Date(pubDate).toISOString() : new Date().toISOString(),
      full_content: null,
      ai_summary: null,
      ai_bullets: null,
      ai_tags: null,
      affected_currency: null,
      market_sentiment: null,
      market_impact_note: null
    }
  });
}

return results;

// Articolele noi vin din „Normalizare & Clasificare”; nodul Postgres anterior întoarce doar
// rândurile existente (full_content / rezumate AI deja calculate), pe care le refolosim.
const dbMap = new Map();
for (const item of $input.all()) {
  const d = item.json || {};
  if (d.article_url) dbMap.set(d.article_url, d);
}

const BBC_IMAGE_PLACEHOLDER = 'https://news.bbcimg.co.uk/nol/shared/img/bbc_news_120x60.gif';
const fixImageUrl = (url) => (url && url.startsWith('http')) ? url : BBC_IMAGE_PLACEHOLDER;

return $('Normalizare & Clasificare').all().map(({ json: article }) => {
  const existing = dbMap.get(article.article_url) || {};
  return {
    json: {
      ...article,
      image_url: fixImageUrl(article.image_url),
      full_content: existing.full_content || article.full_content || null,
      ai_summary: existing.ai_summary || article.ai_summary || null,
      ai_bullets: existing.ai_bullets || null,
      ai_tags: existing.ai_tags || null,
      affected_currency: existing.affected_currency || null,
      market_sentiment: existing.market_sentiment || null,
      market_impact_note: existing.market_impact_note || null
    }
  };
});

// Extragere text complet din pagina articolului BBC
const CONCURRENCY = 5;
const MAX_FETCHES = 150;
const TIMEOUT_MS = 10000;

function extractBBCContent(html) {
  const stripHtml = (s) => s
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<style[\s\S]*?<\/style>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&#39;|&apos;/g, "'")
    .replace(/\s+/g, ' ').trim();

  const blocks = [];
  const articleMatch = html.match(/<article[\s\S]*?<\/article>/i);
  const scope = articleMatch ? articleMatch[0] : html;
  const paragraphs = scope.match(/<p\b[^>]*>[\s\S]*?<\/p>/gi) || [];
  for (const p of paragraphs) {
    const text = stripHtml(p);
    if (text.length > 40) blocks.push(text);
  }
  if (blocks.length === 0) {
    const divs = scope.match(/<div[^>]*data-component="text-block"[^>]*>[\s\S]*?<\/div>/gi) || [];
    for (const d of divs) {
      const text = stripHtml(d);
      if (text.length > 40) blocks.push(text);
    }
  }
  if (blocks.length === 0) return null;
  return blocks.join('\n\n').slice(0, 15000);
}

async function fetchContent(article) {
  if (!this.helpers || typeof this.helpers.httpRequest !== 'function') return;
  try {
    const html = await this.helpers.httpRequest({
      method: 'GET',
      url: article.article_url,
      timeout: TIMEOUT_MS,
      headers: {
        'User-Agent': 'Mozilla/5.0 (compatible; NewsFilterBot/2.0)',
        Accept: 'text/html,application/xhtml+xml'
      },
      json: false
    });
    if (typeof html === 'string') {
      const content = extractBBCContent(html);
      if (content) article.full_content = content;
    }
  } catch (e) {
    // timeout / blocat - continuam fara
  }
}

const articles = $input.all().map(i => ({ ...i.json }));
const needsFetch = articles.filter(a => !a.full_content).slice(0, MAX_FETCHES);
const fetchContentBound = fetchContent.bind(this);

for (let i = 0; i < needsFetch.length; i += CONCURRENCY) {
  const batch = needsFetch.slice(i, i + CONCURRENCY);
  await Promise.all(batch.map(a => fetchContentBound(a)));
}

return articles.map(json => ({ json }));

// Smart Digest cu Gemini Flash Lite: rezumat + 2-3 idei cheie (TL;DR) + etichete + impact pe piața valutară,
// într-un singur apel JSON.
const GEMINI_API_KEY = $env.GEMINI_API_KEY || '';
const GEMINI_URL = `https://generativelanguage.googleapis.com/v1beta/models/gemini-flash-lite-latest:generateContent?key=${GEMINI_API_KEY}`;
const CONCURRENCY = 3;
const MAX_PER_RUN = 50;
// Singurele perechi acceptate (identice cu cele din market_rates și din aplicație).
const MARKET_PAIRS = ['EUR/RON', 'USD/RON', 'BTC/USD'];
const SENTIMENTS = ['UP', 'DOWN', 'NEUTRAL'];

const articles = $input.all().map(i => ({ ...i.json }));
if (!GEMINI_API_KEY) return articles.map(json => ({ json }));

// market_sentiment = marcaj „analizat pentru piață” (NEUTRAL și fără pereche): articolele mai vechi,
// fără el, sunt reprocesate treptat (max. MAX_PER_RUN pe rulare).
const hasDigest = (a) => a.ai_summary && Array.isArray(a.ai_bullets) && a.ai_bullets.length > 0 && !!a.market_sentiment;
const toProcess = articles.filter(a => a.full_content && !hasDigest(a)).slice(0, MAX_PER_RUN);

const cleanList = (value, max, maxLen) => (Array.isArray(value) ? value : [])
  .map(v => String(v || '').replace(/^[-•*\s]+/, '').trim())
  .filter(v => v.length > 0)
  .map(v => v.slice(0, maxLen))
  .slice(0, max);

async function digestArticle(article) {
  const text = article.full_content.slice(0, 8000);
  const prompt = `Esti redactor de stiri. Analizeaza articolul si raspunde DOAR cu un obiect JSON valid, in limba ROMANA, cu structura:
{"summary": "rezumat de 3-4 propozitii", "bullets": ["idee cheie 1", "idee cheie 2", "idee cheie 3"], "tags": ["eticheta 1", "eticheta 2"], "affected_currency": "EUR/RON", "market_sentiment": "UP", "market_impact_note": "o propozitie"}
Reguli: "bullets" are 2-3 elemente, fiecare sub 20 de cuvinte, cu informatia esentiala; "tags" are 2-4 etichete scurte (1-2 cuvinte, litere mici) despre subiecte, persoane, locuri sau organizatii. Nu inventa informatii.
"affected_currency" este UNA dintre perechile EUR/RON, USD/RON, BTC/USD, doar daca stirea poate influenta clar cursul acelei perechi; altfel null. "market_sentiment" este directia probabila a perechii: "UP" = prima moneda se apreciaza fata de a doua, "DOWN" = se depreciaza, "NEUTRAL" = impact neclar (obligatoriu "NEUTRAL" cand affected_currency este null). "market_impact_note" este o singura propozitie (sub 25 de cuvinte) care explica impactul, sau null cand affected_currency este null.

Titlu: ${article.title}

Continut:
${text}`;
  try {
    const response = await this.helpers.httpRequest({
      method: 'POST',
      url: GEMINI_URL,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        contents: [{ parts: [{ text: prompt }] }],
        generationConfig: { temperature: 0.3, maxOutputTokens: 1000, responseMimeType: 'application/json' }
      }),
      json: false,
      timeout: 20000
    });
    const data = typeof response === 'string' ? JSON.parse(response) : response;
    const raw = (data?.candidates?.[0]?.content?.parts?.[0]?.text || '').replace(/^```(?:json)?|```$/g, '').trim();
    const parsed = JSON.parse(raw);
    const summary = String(parsed.summary || '').trim();
    const bullets = cleanList(parsed.bullets, 3, 220);
    const tags = cleanList(parsed.tags, 4, 30).map(t => t.toLowerCase());
    if (summary) article.ai_summary = summary;
    if (bullets.length >= 2) article.ai_bullets = bullets;
    if (tags.length > 0) article.ai_tags = tags;
    // Impact pe piață: doar perechi din listă; altfel „analizat, fără impact” (NEUTRAL, fără pereche).
    const pair = String(parsed.affected_currency || '').toUpperCase().replace(/\s+/g, '');
    const sentiment = String(parsed.market_sentiment || '').toUpperCase();
    if (MARKET_PAIRS.includes(pair)) {
      article.affected_currency = pair;
      article.market_sentiment = SENTIMENTS.includes(sentiment) ? sentiment : 'NEUTRAL';
      article.market_impact_note = String(parsed.market_impact_note || '').trim().slice(0, 220) || null;
    } else {
      article.affected_currency = null;
      article.market_sentiment = 'NEUTRAL';
      article.market_impact_note = null;
    }
  } catch (e) {
    // eroare API / JSON invalid - articolul rămâne cu rezumatul anterior (sau fără)
  }
}

const digestBound = digestArticle.bind(this);
for (let i = 0; i < toProcess.length; i += CONCURRENCY) {
  await Promise.all(toProcess.slice(i, i + CONCURRENCY).map(a => digestBound(a)));
}

const updated = new Map(toProcess.map(a => [a.article_url, a]));
return articles.map(a => ({ json: updated.get(a.article_url) || a }));

