WITH s AS (
  UPDATE sessions SET last_used_at = NOW()
  WHERE token_hash = encode(digest($1, 'sha256'), 'hex') AND revoked_at IS NULL AND expires_at > NOW()
  RETURNING user_id
), recent AS (
  SELECT 1 FROM refresh_requests WHERE requested_at > NOW() - INTERVAL '3 minutes' LIMIT 1
), ins AS (
  INSERT INTO refresh_requests (user_id)
  SELECT user_id FROM s WHERE NOT EXISTS (SELECT 1 FROM recent)
  RETURNING id
)
SELECT (SELECT user_id::text FROM s) AS user_id, (SELECT count(*) FROM ins) > 0 AS accepted;

