const r = $input.first().json || {};
if (!r.user_id) return [{ json: { accepted: false, statusCode: 401, body: { status: 'error', message: 'Sesiune invalidă sau expirată' } } }];
if (!r.accepted) return [{ json: { accepted: false, statusCode: 429, body: { status: 'error', message: 'O actualizare a fost pornită recent. Încearcă din nou peste câteva minute.' } } }];
return [{ json: { accepted: true, statusCode: 202, body: { status: 'started', message: 'Actualizarea surselor a pornit.' } } }];

// Market Pulse: cursuri live. BCE (Frankfurter) pentru EUR/RON și USD/RON, CoinGecko pentru BTC/USD.
// Cursurile BCE se schimbă o dată pe zi lucrătoare → le cerem cel mult o dată la 30 de minute
// (static data; persistă doar la rulările automate). BTC se actualizează la fiecare rulare.
// O sursă care eșuează nu emite nimic, iar rândul ei din market_rates rămâne neschimbat.
//
// Istoric pentru grafic (`history`, puncte zilnice, salvate cu is_daily = TRUE):
//  - fiat: ultimele 30 de zile la fiecare cerere BCE, iar o dată pe zi ultimii 5 ani
//    (fixarea BCE ~16:00 CET = 14:00 UTC);
//  - BTC: o dată pe zi ultimele 365 de zile (limita planului gratuit CoinGecko), la 00:00 UTC.
const FIAT_TTL_MS = 30 * 60 * 1000;
const LONG_TTL_MS = 24 * 60 * 60 * 1000;
const DAY_MS = 86400000;
const staticData = $getWorkflowStaticData('global');
const now = Date.now();
const round = (v, d) => Number(Number(v).toFixed(d));
const pct = (cur, prev) => (prev ? round((cur - prev) / prev * 100, 4) : null);
const due = (key, ttl) => !staticData[key] || now - staticData[key] > ttl;
const out = [];

async function getJson(url) {
  const res = await this.helpers.httpRequest({
    method: 'GET', url, timeout: 20000, json: true,
    headers: { Accept: 'application/json', 'User-Agent': 'NewsFilterBot/2.0' }
  });
  return typeof res === 'string' ? JSON.parse(res) : res;
}
const get = getJson.bind(this);

// 1. Fiat (BCE): curs + variație față de ziua lucrătoare anterioară + istoric zilnic.
if (due('fiatFetchedAt', FIAT_TTL_MS)) {
  const longFetch = due('fiatLongFetchedAt', LONG_TTL_MS);
  try {
    const start = new Date(now - (longFetch ? 5 * 366 : 30) * DAY_MS).toISOString().slice(0, 10);
    const data = await get(`https://api.frankfurter.dev/v1/${start}..?base=EUR&symbols=RON,USD`);
    const days = Object.keys(data.rates || {}).sort();
    const last = days.length ? data.rates[days[days.length - 1]] : null;
    const prev = days.length > 1 ? data.rates[days[days.length - 2]] : null;
    const history = (fn) => days.map(d => ({ recorded_at: `${d}T14:00:00Z`, rate: fn(data.rates[d]) }))
      .filter(h => Number.isFinite(h.rate) && h.rate > 0)
      .map(h => ({ ...h, rate: round(h.rate, 6) }));
    if (last && last.RON) {
      out.push({ pair: 'EUR/RON', rate: round(last.RON, 6), change_percent: pct(last.RON, prev && prev.RON), source: 'BCE (Frankfurter)', history: history(r => r.RON) });
      if (last.USD) {
        const usdRon = last.RON / last.USD;
        const prevUsdRon = prev && prev.RON && prev.USD ? prev.RON / prev.USD : null;
        out.push({ pair: 'USD/RON', rate: round(usdRon, 6), change_percent: pct(usdRon, prevUsdRon), source: 'BCE (Frankfurter)', history: history(r => r.RON / r.USD) });
      }
      staticData.fiatFetchedAt = now;
      if (longFetch) staticData.fiatLongFetchedAt = now;
    }
  } catch (e) {
    // API indisponibil - reîncercăm la rularea următoare
  }
}

// 2. Crypto (CoinGecko): preț + variație pe 24h; o dată pe zi și istoricul pe 365 de zile.
try {
  const data = await get('https://api.coingecko.com/api/v3/simple/price?ids=bitcoin&vs_currencies=usd&include_24hr_change=true');
  const btc = data && data.bitcoin;
  if (btc && typeof btc.usd === 'number') {
    const item = {
      pair: 'BTC/USD',
      rate: round(btc.usd, 2),
      change_percent: typeof btc.usd_24h_change === 'number' ? round(btc.usd_24h_change, 4) : null,
      source: 'CoinGecko'
    };
    if (due('btcLongFetchedAt', LONG_TTL_MS)) {
      try {
        const chart = await get('https://api.coingecko.com/api/v3/coins/bitcoin/market_chart?vs_currency=usd&days=365&interval=daily');
        const byDay = new Map();
        for (const [ms, price] of (chart && chart.prices) || []) {
          if (Number.isFinite(price) && price > 0) byDay.set(Math.floor(ms / DAY_MS) * DAY_MS, round(price, 2));
        }
        item.history = [...byDay.entries()].map(([day, rate]) => ({ recorded_at: new Date(day).toISOString(), rate }));
        if (item.history.length) staticData.btcLongFetchedAt = now;
      } catch (e) {
        // istoricul se reîncearcă la rularea următoare
      }
    }
    out.push(item);
  }
} catch (e) {
  // limită de cereri / API indisponibil - păstrăm ultimul curs salvat
}

return out.map(json => ({ json }));
